package edu.smartstudy.focus;
import jakarta.persistence.*;import java.time.*;
@Entity @Table(name="focus_sessions") public class FocusSession{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="student_id",nullable=false)private Long studentId;@Column(name="task_id")private Long taskId;@Column(name="started_at",nullable=false,insertable=false,updatable=false)private Instant startedAt;@Column(name="active_since")private Instant activeSince;@Column(name="ended_at")private Instant endedAt;@Column(name="duration_seconds",nullable=false)private int durationSeconds;@Column(nullable=false)private String status="ACTIVE";protected FocusSession(){}public FocusSession(Long studentId,Long taskId){this.studentId=studentId;this.taskId=taskId;activeSince=Instant.now();}public Long getId(){return id;}public Long getStudentId(){return studentId;}public Long getTaskId(){return taskId;}public Instant getStartedAt(){return startedAt;}public Instant getEndedAt(){return endedAt;}public int getDurationSeconds(){return durationSeconds;}public String getStatus(){return status;}public void pause(){if("ACTIVE".equals(status)&&activeSince!=null){durationSeconds+=Math.max(0,(int)Duration.between(activeSince,Instant.now()).getSeconds());activeSince=null;status="PAUSED";}}public void resume(){if("PAUSED".equals(status)){activeSince=Instant.now();status="ACTIVE";}}public void finish(){if("ACTIVE".equals(status)&&activeSince!=null)durationSeconds+=Math.max(0,(int)Duration.between(activeSince,Instant.now()).getSeconds());activeSince=null;endedAt=Instant.now();status="COMPLETED";}}
